import{_ as a,o as s,c as o,a6 as n}from"./chunks/framework.DMOj2-2K.js";const h=JSON.parse('{"title":"Cluub Language Reference (v0.1)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/language.md","filePath":"reference/language.md"}'),t={name:"reference/language.md"};function d(c,e,i,l,p,r){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="cluub-language-reference-v0-1" tabindex="-1">Cluub Language Reference (v0.1) <a class="header-anchor" href="#cluub-language-reference-v0-1" aria-label="Permalink to &quot;Cluub Language Reference (v0.1)&quot;">​</a></h1><p>Cluub is one language for frontend, backend and AI. Code reads like plain English, blocks are defined by <strong>2-space indentation</strong>, and every project has the <strong>same structure</strong>, enforced by the compiler. This file is the complete reference; it is also what <code>cluub make</code> gives the AI so generated code follows the same rules.</p><h2 id="_1-project-layout-enforced-error-e301" tabindex="-1">1. Project layout (enforced, error E301) <a class="header-anchor" href="#_1-project-layout-enforced-error-e301" aria-label="Permalink to &quot;1. Project layout (enforced, error E301)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Folder</th><th>Holds</th><th>Layer</th></tr></thead><tbody><tr><td><code>app.clb</code></td><td>the single <code>app</code> declaration</td><td>config</td></tr><tr><td><code>models/</code></td><td><code>model</code></td><td>data shapes + validation</td></tr><tr><td><code>data/</code></td><td><code>store</code></td><td>data layer</td></tr><tr><td><code>network/</code></td><td><code>client</code></td><td>network layer (outside APIs)</td></tr><tr><td><code>services/</code></td><td><code>service</code></td><td>business logic, AI</td></tr><tr><td><code>api/</code></td><td><code>api</code></td><td>HTTP endpoints</td></tr><tr><td><code>ui/pages/</code>, <code>ui/components/</code>, <code>ui/layouts/</code></td><td><code>page</code>, <code>component</code>, <code>layout</code></td><td>UI layer</td></tr><tr><td><code>tests/</code></td><td><code>test</code> (generated tests go to <code>tests/generated/</code>)</td><td>tests</td></tr></tbody></table><h2 id="_2-layer-rules-enforced-error-e201" tabindex="-1">2. Layer rules (enforced, error E201) <a class="header-anchor" href="#_2-layer-rules-enforced-error-e201" aria-label="Permalink to &quot;2. Layer rules (enforced, error E201)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>page ──uses──▶ api ──uses──▶ service ──uses──▶ store | client | service</span></span>
<span class="line"><span>component / layout: no dependencies (they receive data with \`takes\`)</span></span></code></pre></div><ul><li>Every dependency is declared with <code>uses X</code> (Dependency Inversion). Using one without <code>uses</code> is error E106.</li><li><code>ask ai</code> and <code>env.X</code> are only allowed in services/apis/clients, never in the UI (E204, E205).</li><li>Services may not depend on each other in a circle (E202).</li><li>A view only shows data: calling an api or an action inside a view expression is E117. Load data into <code>state</code> in <code>when loaded</code> or an action.</li></ul><h2 id="_3-naming-enforced" tabindex="-1">3. Naming (enforced) <a class="header-anchor" href="#_3-naming-enforced" aria-label="Permalink to &quot;3. Naming (enforced)&quot;">​</a></h2><p>Declarations are <code>PascalCase</code> (E102). Fields, actions, state, params and values are <code>camelCase</code> (E103).</p><h2 id="_4-lexical-rules" tabindex="-1">4. Lexical rules <a class="header-anchor" href="#_4-lexical-rules" aria-label="Permalink to &quot;4. Lexical rules&quot;">​</a></h2><ul><li>Comments start with <code>#</code>.</li><li>Text uses double quotes: <code>&quot;Hello {name}&quot;</code>. <code>{expr}</code> interpolates. <code>&quot;&quot;&quot;triple quotes&quot;&quot;&quot;</code> span lines (great for prompts). Escape braces as <code>\\{</code>.</li><li>Numbers: <code>42</code>, <code>3.5</code>, <code>1_000</code>. Booleans: <code>true</code>/<code>false</code> (or <code>yes</code>/<code>no</code>). Missing value: <code>nothing</code>.</li><li>Lists <code>[1, 2]</code>, objects <code>{name: &quot;Ada&quot;, age: 36}</code>. A trailing comma is allowed: <code>[1, 2, 3,]</code>.</li><li>Symbols <code>==</code>, <code>!=</code>, <code>&amp;&amp;</code>, <code>||</code>, <code>!</code> are errors (E006); use words.</li></ul><h2 id="_5-declarations" tabindex="-1">5. Declarations <a class="header-anchor" href="#_5-declarations" aria-label="Permalink to &quot;5. Declarations&quot;">​</a></h2><h3 id="app" tabindex="-1">app <a class="header-anchor" href="#app" aria-label="Permalink to &quot;app&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>app ShopApp</span></span>
<span class="line"><span>  about &quot;What the app is&quot;</span></span>
<span class="line"><span>  port 3000</span></span>
<span class="line"><span>  ai &quot;claude&quot;              # claude | openai | gemini | ollama, or &quot;claude:claude-sonnet-5-5&quot;</span></span>
<span class="line"><span>  aiKeys &quot;server&quot;          # whose keys pay: &quot;server&quot; (.env), &quot;user&quot; (each end user&#39;s own key) or &quot;either&quot;</span></span></code></pre></div><h3 id="model" tabindex="-1">model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;model&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>model Customer</span></span>
<span class="line"><span>  about &quot;A person who buys things&quot;</span></span>
<span class="line"><span>  name: text, required, min 2, max 80</span></span>
<span class="line"><span>  email: email, required &quot;We need an email to send receipts&quot;</span></span>
<span class="line"><span>  age: number = 0, min 0</span></span>
<span class="line"><span>  tier: text = &quot;free&quot;, one of [&quot;free&quot;, &quot;pro&quot;]</span></span>
<span class="line"><span>  tags: list of text = []</span></span>
<span class="line"><span>  notes: text?               # ? = optional</span></span></code></pre></div><p>Types: <code>text number bool email url date id any list of T</code>, a model name, or <code>T?</code>. Rules: <code>required</code>, <code>min N</code>, <code>max N</code>, <code>one of [...]</code>, each with an optional custom message. Every model also has an optional <code>id</code>. Create one with named values: <code>Customer(name: &quot;Ada&quot;, email: &quot;a@b.co&quot;)</code>. Invalid values fail with precise messages (&quot;name must be at least 2 characters&quot;).</p><h3 id="store-data-layer" tabindex="-1">store (data layer) <a class="header-anchor" href="#store-data-layer" aria-label="Permalink to &quot;store (data layer)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>store Customers holds Customer                          # in memory</span></span>
<span class="line"><span>store Orders holds Order saved in &quot;storage/orders.json&quot; # persisted</span></span></code></pre></div><p>Methods: <code>all()</code>, <code>find(id)</code> (nothing if missing), <code>get(id)</code> (fails 404 if missing), <code>add(item)</code>, <code>update(id, changes)</code>, <code>remove(id)</code>, <code>where(x =&gt; condition)</code>, <code>count()</code>, <code>clear()</code>.</p><h3 id="client-network-layer" tabindex="-1">client (network layer) <a class="header-anchor" href="#client-network-layer" aria-label="Permalink to &quot;client (network layer)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>client Weather at &quot;https://api.open-meteo.com/v1&quot;</span></span>
<span class="line"><span>  header &quot;User-Agent&quot; &quot;my-app&quot;</span></span>
<span class="line"><span>  get forecast at &quot;/forecast&quot; with latitude: number, longitude: number</span></span></code></pre></div><h3 id="service-business-logic" tabindex="-1">service (business logic) <a class="header-anchor" href="#service-business-logic" aria-label="Permalink to &quot;service (business logic)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>service OrderService</span></span>
<span class="line"><span>  about &quot;Placing and tracking orders&quot;</span></span>
<span class="line"><span>  uses Orders, Customers</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  action place(customerId: text, total: number) -&gt; Order</span></span>
<span class="line"><span>    about &quot;Place a new order&quot;</span></span>
<span class="line"><span>    require total &gt; 0, &quot;Total must be positive&quot;</span></span>
<span class="line"><span>    let customer = Customers.get(customerId)</span></span>
<span class="line"><span>    return Orders.add(Order(customerId: customer.id, total: total))</span></span></code></pre></div><h3 id="api-backend-endpoints" tabindex="-1">api (backend endpoints) <a class="header-anchor" href="#api-backend-endpoints" aria-label="Permalink to &quot;api (backend endpoints)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>api OrderApi at &quot;/api/orders&quot;</span></span>
<span class="line"><span>  uses OrderService</span></span>
<span class="line"><span>  get list at &quot;/&quot;</span></span>
<span class="line"><span>    return OrderService.all()</span></span>
<span class="line"><span>  get one at &quot;/{id}&quot;                 # {id} becomes a text parameter</span></span>
<span class="line"><span>    return OrderService.get(id)</span></span>
<span class="line"><span>  post place at &quot;/&quot; with customerId: text, total: number</span></span>
<span class="line"><span>    return OrderService.place(customerId, total)</span></span>
<span class="line"><span>  delete remove at &quot;/{id}&quot;</span></span>
<span class="line"><span>    OrderService.remove(id)</span></span></code></pre></div><p>Parameters come from the path, the query string (get/delete) or the JSON body (post/put/patch), are type-checked automatically, and missing or invalid values return 400 with a clear message.</p><h3 id="page-ui" tabindex="-1">page (UI) <a class="header-anchor" href="#page-ui" aria-label="Permalink to &quot;page (UI)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>page Orders at &quot;/orders&quot;</span></span>
<span class="line"><span>  about &quot;Lists orders&quot;</span></span>
<span class="line"><span>  title &quot;Orders&quot;</span></span>
<span class="line"><span>  layout Main</span></span>
<span class="line"><span>  uses OrderApi</span></span>
<span class="line"><span>  state orders = []</span></span>
<span class="line"><span>  state total = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  when loaded</span></span>
<span class="line"><span>    orders = OrderApi.list()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  action place()</span></span>
<span class="line"><span>    OrderApi.place(customerId: &quot;1&quot;, total: total)</span></span>
<span class="line"><span>    orders = OrderApi.list()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  view</span></span>
<span class="line"><span>    heading &quot;Orders&quot;</span></span>
<span class="line"><span>    row</span></span>
<span class="line"><span>      input total, type &quot;number&quot;, placeholder &quot;Total&quot;</span></span>
<span class="line"><span>      button &quot;Place order&quot;, on click place, style primary, disabled total is 0</span></span>
<span class="line"><span>    for order in orders</span></span>
<span class="line"><span>      OrderCard order: order</span></span>
<span class="line"><span>    if orders is empty</span></span>
<span class="line"><span>      text &quot;No orders yet.&quot;</span></span></code></pre></div><p>Calls to apis are awaited automatically. Errors from the server appear as a message toast automatically. Path params (<code>at &quot;/orders/{id}&quot;</code>) are available by name (<code>id</code>). <code>go to &quot;/path&quot;</code> navigates.</p><h3 id="component-and-layout" tabindex="-1">component and layout <a class="header-anchor" href="#component-and-layout" aria-label="Permalink to &quot;component and layout&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>component OrderCard</span></span>
<span class="line"><span>  takes order: Order, onCancel: action</span></span>
<span class="line"><span>  view</span></span>
<span class="line"><span>    card</span></span>
<span class="line"><span>      text &quot;Order {order.id}: {order.total}&quot;</span></span>
<span class="line"><span>      button &quot;Cancel&quot;, on click onCancel(order.id), style danger</span></span>
<span class="line"><span></span></span>
<span class="line"><span>layout Main</span></span>
<span class="line"><span>  view</span></span>
<span class="line"><span>    header</span></span>
<span class="line"><span>      link &quot;Home&quot; to &quot;/&quot;</span></span>
<span class="line"><span>    slot                     # the page goes here</span></span>
<span class="line"><span>    footer</span></span>
<span class="line"><span>      text &quot;© 2026&quot;</span></span></code></pre></div><p>Components have no state and no dependencies; pages own data (smart page / simple component pattern).</p><h3 id="view-elements" tabindex="-1">View elements <a class="header-anchor" href="#view-elements" aria-label="Permalink to &quot;View elements&quot;">​</a></h3><p>Content: <code>heading</code>, <code>subheading</code>, <code>text</code>, <code>label</code>, <code>badge</code>, <code>item</code>, <code>button</code>, <code>link ... to</code>, <code>image</code>, <code>input</code>, <code>checkbox</code>, <code>select ..., options [...]</code>. Containers: <code>row</code>, <code>column</code>, <code>card</code>, <code>box</code>, <code>grid</code>, <code>list</code>, <code>header</code>, <code>footer</code>, <code>nav</code>, <code>section</code>, <code>form</code>. Others: <code>divider</code>, <code>spinner</code>, <code>slot</code>, <code>aikey</code> (built-in form where an end user adds or forgets their own AI key). Control: <code>for x in list</code>, <code>if cond</code> / <code>else</code>. Components: <code>Name prop: value, other: value</code>. Properties (after a comma): <code>on click|change|enter|submit|input action</code>, <code>placeholder &quot;...&quot;</code>, <code>type &quot;number&quot;</code>, <code>disabled cond</code>, <code>style primary|danger|ghost|muted</code>, <code>class &quot;...&quot;</code>, <code>alt &quot;...&quot;</code>, <code>multiline</code>, <code>options [...]</code>. Event blocks: an indented <code>on click</code> line followed by statements.</p><h3 id="test" tabindex="-1">test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;test&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>test &quot;placing an order&quot;</span></span>
<span class="line"><span>  let order = OrderService.place(&quot;1&quot;, 20)</span></span>
<span class="line"><span>  expect order.total is 20</span></span>
<span class="line"><span>  expect OrderService.place(&quot;1&quot;, 0) fails with &quot;Total must be positive&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>test &quot;the orders page works&quot;</span></span>
<span class="line"><span>  render Orders</span></span>
<span class="line"><span>  type &quot;20&quot; into &quot;Total&quot;</span></span>
<span class="line"><span>  click &quot;Place order&quot;</span></span>
<span class="line"><span>  expect screen has &quot;Order&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>test &quot;the api validates input&quot;</span></span>
<span class="line"><span>  let response = request post &quot;/api/orders&quot; with {total: &quot;abc&quot;}</span></span>
<span class="line"><span>  expect response.status is 400</span></span></code></pre></div><p>Every test gets fresh in-memory stores, a fake AI and no network. <code>cluub test</code> also <strong>generates</strong> tests for every model rule, <code>require</code>, api route, page and button.</p><h2 id="_6-statements" tabindex="-1">6. Statements <a class="header-anchor" href="#_6-statements" aria-label="Permalink to &quot;6. Statements&quot;">​</a></h2><p><code>let x = value</code>, <code>x = value</code>, <code>return value</code>, <code>require cond, &quot;message&quot;</code> (fails with 400), <code>fail &quot;message&quot;</code> or <code>fail &quot;message&quot; status 404</code>, <code>if / else if / else</code>, <code>for x in list</code>, <code>while cond</code>, <code>try</code> … <code>catch problem</code> (problem.message, problem.status), <code>log value</code>, <code>go to &quot;/path&quot;</code>.</p><h2 id="_7-expressions" tabindex="-1">7. Expressions <a class="header-anchor" href="#_7-expressions" aria-label="Permalink to &quot;7. Expressions&quot;">​</a></h2><ul><li>Comparison: <code>is</code>, <code>is not</code>, <code>&lt;</code>, <code>&gt;</code>, <code>&lt;=</code>, <code>&gt;=</code>, <code>is greater than</code>, <code>is less than</code>, <code>is at least</code>, <code>is at most</code>, <code>is more than</code>, <code>is fewer than</code>, <code>is empty</code>, <code>is not empty</code>, <code>is one of [...]</code>, <code>has</code> (text/list contains), <code>equals</code>.</li><li>Logic: <code>and</code>, <code>or</code>, <code>not</code>. Math: <code>+ - * / %</code> or <code>plus minus times divided by</code>.</li><li>Lists/text: <code>.count</code>, <code>.first</code>, <code>.last</code>, <code>.where(x =&gt; ...)</code>, <code>.map(x =&gt; ...)</code>, <code>.sortBy(x =&gt; ...)</code>, <code>.contains(x)</code>, <code>.add(x)</code>, <code>.upper()</code>, <code>.lower()</code>, <code>.trim()</code>.</li><li>Built-ins: <code>now()</code>, <code>today()</code>, <code>round(x, digits)</code>, <code>text(x)</code>, <code>number(x)</code>, <code>uuid()</code>, <code>json(x)</code>, <code>random(a, b)</code>, <code>sleep(ms)</code>, <code>hasAiKey()</code> (UI: has the end user saved their own AI key), <code>env.NAME</code> (backend only). In tests: <code>screen</code>.</li></ul><h2 id="_8-ai" tabindex="-1">8. AI <a class="header-anchor" href="#_8-ai" aria-label="Permalink to &quot;8. AI&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>let summary = ask ai &quot;Summarize: {text}&quot;</span></span>
<span class="line"><span>let contact = ask ai &quot;Extract the contact from: {email}&quot; as Contact     # structured, validated</span></span>
<span class="line"><span>let kind = ask ai &quot;Bug or feature? {report}&quot; as one of [&quot;bug&quot;, &quot;feature&quot;]</span></span>
<span class="line"><span>let fr = ask ai &quot;Translate to French: {t}&quot; using &quot;openai&quot; with system &quot;You are a translator&quot;</span></span></code></pre></div><p>Providers: Claude (<code>ANTHROPIC_API_KEY</code>), OpenAI (<code>OPENAI_API_KEY</code>), Gemini (<code>GEMINI_API_KEY</code>), Ollama (local, no key). Cluub is bring-your-own-key: it never ships or proxies a key. Developers add keys with <code>cluub ai set &lt;provider&gt;</code> (stored in <code>.env</code>); hard-coded keys are a compile error (E401). With <code>aiKeys &quot;user&quot;</code> each end user&#39;s key stays in their browser and is sent only with their requests.</p><h2 id="_9-spoken-voice-dictation-friendly" tabindex="-1">9. Spoken (voice / dictation) friendly <a class="header-anchor" href="#_9-spoken-voice-dictation-friendly" aria-label="Permalink to &quot;9. Spoken (voice / dictation) friendly&quot;">​</a></h2><p>Everything is words: &quot;if total is greater than 100&quot;, &quot;let price equal…&quot; is written <code>let price = …</code>, &quot;divided by&quot;, &quot;plus&quot;, &quot;is not empty&quot;. Dictated code works with tools like Wispr Flow.</p>`,47)])])}const m=a(t,[["render",d]]);export{h as __pageData,m as default};
